const menuButton=document.querySelector('.menu-toggle');const menu=document.querySelector('.menu');menuButton?.addEventListener('click',()=>{const open=menu.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});document.querySelectorAll('.menu a').forEach(a=>a.addEventListener('click',()=>{menu.classList.remove('open');menuButton?.setAttribute('aria-expanded','false')}));
const tabs=[...document.querySelectorAll('.tab')];tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(t=>t.classList.remove('active'));document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));tab.classList.add('active');document.getElementById(tab.dataset.tab)?.classList.add('active')}));
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
document.getElementById('lead-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const text=`Olá, sou ${data.get('nome')}, da empresa ${data.get('empresa')}. Meu principal desafio é: ${data.get('desafio')}. Vim pelo site da Hunt Digital e gostaria de conversar.`;window.open(`https://wa.me/553199617435?text=${encodeURIComponent(text)}`,'_blank','noopener')});
